files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #e0e0f0;
  --accent: #7c5cbf;
  --accent-hover: #9b7edb;
  --accent-active: #5a3f9e;
  --border: #4a4a6a;
  --success: #4caf7a;
  --danger: #e05c5c;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}

.desk {
  background: var(--card);
  border-radius: 16px;
  padding: 28px 24px;
  width: 100%;
  max-width: 560px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.desk-header h1 {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: #fff;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0c0;
  margin-bottom: 20px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.filter-label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 1rem;
  color: var(--text);
  user-select: none;
}

.filter-label input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
}

.filter-label input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.count {
  font-size: 1rem;
  font-weight: 600;
  color: var(--accent-hover);
}

.book-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.book-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  background: #22223a;
  border: 1px solid var(--border);
  border-radius: 10px;
}

.book-info {
  flex: 1 1 180px;
  min-width: 0;
}

.book-title {
  font-size: 1.05rem;
  font-weight: 600;
  color: #fff;
  margin-bottom: 2px;
  overflow-wrap: break-word;
}

.book-author {
  font-size: 0.9rem;
  color: #a0a0c0;
  margin-bottom: 4px;
}

.book-status {
  font-size: 0.9rem;
  font-weight: 600;
}

.book-status.available {
  color: var(--success);
}

.book-status.checked-out {
  color: var(--danger);
}

.book-action {
  font-family: var(--font);
  font-size: 0.95rem;
  font-weight: 600;
  padding: 8px 18px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  background: var(--accent);
  color: #fff;
  transition: background 0.15s ease, transform 0.05s ease;
  flex-shrink: 0;
}

.book-action:hover {
  background: var(--accent-hover);
}

.book-action:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.book-action:active {
  background: var(--accent-active);
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .desk {
    padding: 20px 14px;
  }
  .desk-header h1 {
    font-size: 1.35rem;
  }
  .book-item {
    padding: 12px;
  }
  .book-action {
    width: 100%;
  }
}

const books = [
  { id: 1, title: 'The Pixel Frontier', author: 'Ada Lovelace', available: true },
  { id: 2, title: 'Cascading Styles', author: 'Håkon Wium Lie', available: false },
  { id: 3, title: 'Event Loop Chronicles', author: 'Ryan Dahl', available: true },
  { id: 4, title: 'DOM Manipulation', author: 'Brendan Eich', available: false },
  { id: 5, title: 'Responsive Realms', author: 'Ethan Marcotte', available: true },
  { id: 6, title: 'Accessible Interfaces', author: 'Léonie Watson', available: true }
];

const bookList = document.getElementById('bookList');
const filterCheckbox = document.getElementById('filterAvailable');
const countDisplay = document.getElementById('checkedOutCount');

function render() {
  const showAvailableOnly = filterCheckbox.checked;
  const checkedOutCount = books.filter(b => !b.available).length;
  countDisplay.textContent = `Checked out: ${checkedOutCount}`;

  bookList.innerHTML = '';

  books.forEach(book => {
    if (showAvailableOnly && !book.available) return;

    const li = document.createElement('li');
    li.className = 'book-item';

    const info = document.createElement('div');
    info.className = 'book-info';

    const title = document.createElement('div');
    title.className = 'book-title';
    title.textContent = book.title;

    const author = document.createElement('div');
    author.className = 'book-author';
    author.textContent = book.author;

    const status = document.createElement('div');
    status.className = `book-status ${book.available ? 'available' : 'checked-out'}`;
    status.textContent = book.available ? 'Available' : 'Checked out';

    info.append(title, author, status);

    const btn = document.createElement('button');
    btn.className = 'book-action';
    btn.type = 'button';
    btn.textContent = book.available ? 'Check Out' : 'Return';
    btn.setAttribute('aria-label', `${btn.textContent} ${book.title}`);
    btn.addEventListener('click', () => {
      book.available = !book.available;
      render();
    });

    li.append(info, btn);
    bookList.appendChild(li);
  });
}

filterCheckbox.addEventListener('change', render);

render();
